setvar VAR_0x8008 FEMALE
setvar VAR_0x8009 LOCALID_PLAYERS_HOUSE_1F_DAD
setvar VAR_0x800A LOCALID_PLAYERS_HOUSE_1F_MOM
return
= PlayersHouse_1F_EventScript_SetUpObjectEventVarsMale
setvar VAR_0x8008 MALE
setvar VAR_0x8009 LOCALID_PLAYERS_HOUSE_1F_DAD
setvar VAR_0x800A LOCALID_PLAYERS_HOUSE_1F_MOM
return
= LittlerootTown_BrendansHouse_1F_EventScript_YoureNewNeighbor
lockall
playse SE_PIN
applymovement LOCALID_RIVALS_HOUSE_1F_MOM Common_Movement_ExclamationMark
waitmovement 0
applymovement LOCALID_RIVALS_HOUSE_1F_MOM Common_Movement_Delay48
waitmovement 0
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterLeft
applymovement LOCALID_RIVALS_HOUSE_1F_MOM LittlerootTown_BrendansHouse_1F_Movement_RivalMomApproach
waitmovement 0
special GetRivalSonDaughterString
msgbox	Oh, hallo. Und du bist?… … … … … … … … … … … … … … … … … …Ach, du bist ja PLAYER, unser neuer Nachbar! Hallo!Unser Kind ist etwa in deinem Alter.Es hat sich schon richtig gefreut, einen neuen Freund kennenzulernen.Ich glaube, unser Kind ist oben.
setflag FLAG_MET_RIVAL_MOM
setvar VAR_LITTLEROOT_HOUSES_STATE_MAY 2
releaseall
end
= LittlerootTown_BrendansHouse_1F_EventScript_PetalburgGymReport
lockall
setvar VAR_0x8004 MALE
setvar VAR_0x8005 LOCALID_PLAYERS_HOUSE_1F_MOM
goto PlayersHouse_1F_EventScript_PetalburgGymReportMale
end
= PlayersHouse_1F_EventScript_PetalburgGymReportMale
applymovement VAR_0x8005 Common_Movement_WalkInPlaceFasterRight
waitmovement 0
call PlayersHouse_1F_EventScript_MomNoticeGymBroadcast
applymovement LOCALID_PLAYER PlayersHouse_1F_Movement_PlayerApproachTVForGymMale
waitmovement 0
playbgm MUS_ENCOUNTER_INTERVIEWER FALSE
msgbox	MOM: Schau! Das ist die PETALBURG GYM! Vielleicht kommt DAD dran!
closemessage
applymovement VAR_0x8005 PlayersHouse_1F_Movement_MomMakeRoomToSeeTVMale
waitmovement 0
applymovement LOCALID_PLAYER PlayersHouse_1F_Movement_PlayerMoveToTVMale
waitmovement 0
call PlayersHouse_1F_EventScript_WatchGymBroadcast
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
msgbox	MOM: Oh… Es ist vorbei.Ich glaube, DAD war dran, aber wir haben ihn verpasst. Wie schade.
msgbox	Ach ja. Einer von DADs Freunden wohnt hier in der Stadt.PROF. BIRCH heißt er.Er wohnt gleich nebenan, du solltest also rübergehen und dich vorstellen.
closemessage
setvar VAR_TEMP_1 1
applymovement VAR_0x8005 PlayersHouse_1F_Movement_MomReturnToSeatMale
waitmovement 0
goto PlayersHouse_1F_EventScript_SetWatchedBroadcast
end
= PlayersHouse_1F_EventScript_SetWatchedBroadcast
setvar VAR_LITTLEROOT_INTRO_STATE 7
releaseall
end
= PlayersHouse_1F_EventScript_WatchGymBroadcast
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterUp
waitmovement 0
msgbox	INTERVIEWER: …Das war unser Bericht direkt von der PETALBURG GYM.
fadedefaultbgm
special TurnOffTVScreen
setflag FLAG_SYS_TV_HOME
delay 35
return
= PlayersHouse_1F_EventScript_MomNoticeGymBroadcast
playse SE_PIN
applymovement VAR_0x8005 Common_Movement_ExclamationMark
waitmovement 0
applymovement VAR_0x8005 Common_Movement_Delay48
waitmovement 0
msgbox	MOM: Oh! PLAYER, PLAYER! Schnell! Komm schnell her!
closemessage
return
= LittlerootTown_BrendansHouse_1F_EventScript_GoUpstairsToSetClock
lockall
msgbox	MOM: PLAYER.Stell doch bitte die Uhr in deinem Zimmer, Schatz.
closemessage
applymovement LOCALID_PLAYER LittlerootTown_BrendansHouse_1F_Movement_PushTowardStairs
applymovement LOCALID_PLAYERS_HOUSE_1F_MOM LittlerootTown_BrendansHouse_1F_Movement_PushTowardStairs
waitmovement 0
warp LittlerootTown_BrendansHouse_2F 7 1
waitstate
releaseall
end
= LittlerootTown_BrendansHouse_1F_EventScript_EnterHouseMovingIn
lockall
setvar VAR_0x8004 LOCALID_PLAYERS_HOUSE_1F_MOM
setvar VAR_0x8005 MALE
goto PlayersHouse_1F_EventScript_EnterHouseMovingIn
end
= PlayersHouse_1F_EventScript_EnterHouseMovingIn
msgbox	MOM: Siehst du, PLAYER? Ist es hier drin nicht auch schön?
applymovement VAR_0x8004 Common_Movement_FacePlayer
waitmovement 0
call_if_eq VAR_0x8005 MALE PlayersHouse_1F_EventScript_MomFacePlayerMovingInMale
call_if_eq VAR_0x8005 FEMALE PlayersHouse_1F_EventScript_MomFacePlayerMovingInFemale
msgbox	Die POKéMON der Umzugsfirma erledigen die ganze Arbeit beim Einzug und räumen danach auch noch auf. Das ist wirklich praktisch!PLAYER, dein Zimmer ist oben. Schau es dir doch mal an, Schatz!DAD hat dir zum Einzug eine neue Uhr gekauft. Vergiss nicht, sie zu stellen!
closemessage
setvar VAR_LITTLEROOT_INTRO_STATE 4
applymovement LOCALID_PLAYER PlayersHouse_1F_Movement_PlayerWalkIn
applymovement VAR_0x8004 Common_Movement_WalkInPlaceFasterUp
waitmovement 0
releaseall
end
= PlayersHouse_1F_EventScript_MomFacePlayerMovingInFemale
